#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* intToRoman(int num) {
    const int vals[] = {1000,900,500,400,100,90,50,40,10,9,5,4,1};
    const char* syms[] = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
    char* out = (char*)malloc(64);
    out[0] = '\0';
    int pos = 0;
    for (int i = 0; i < 13 && num > 0; ++i) {
        while (num >= vals[i]) {
            const char* s = syms[i];
            int l = (int)strlen(s);
            if (pos + l + 1 > 64) {
                out = (char*)realloc(out, pos + l + 64);
            }
            strcpy(out + pos, s);
            pos += l;
            out[pos] = '\0';
            num -= vals[i];
        }
    }
    return out;
}

int main(void) {
    char line[256];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    int len = (int)strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = '\0';
    if (len >= 2) {
        char inner[64];
        strncpy(inner, line+1, len-2);
        inner[len-2] = '\0';
        int num = atoi(inner);
        char* res = intToRoman(num);
        printf("\"%s\"\n", res);
        free(res);
    }
    return 0;
}

